#include "webrc/dsp/preamp_fx.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdint>
#include <cstdio>
extern "C" double gPreCabinetPeak = 0.0;
extern "C" std::uint64_t gPreCabinetSamplesOver16 = 0U;
namespace { using namespace webrc::dsp; constexpr double pi=3.141592653589793238462643383279502884; constexpr std::uint32_t sr=48000U, frames=sr, block=64U, windowFrames=8192U; struct Case{const char*name;double hz;}; struct Result{const char*name;double prePeak;std::uint64_t over;double outPeak;double outRms;double fundamental;double thd;};
Result run(Case item){ProcessSpec spec{48000.0f,block,2U}; std::array<float,1> ir{1.0f}; PreampFxProcessor proc; PreampFxOptions opt{}; if(!proc.prepare(spec,opt,{1U,ir.data(),ir.data()})) return {item.name,-1,0,-1,-1,-1,-1}; const std::array<PreampFxEvent,8> ev{{{0,PreampFxControl::Active,1},{0,PreampFxControl::Mix,1},{0,PreampFxControl::Drive,24},{0,PreampFxControl::BassDb,12},{0,PreampFxControl::MidDb,12},{0,PreampFxControl::TrebleDb,12},{0,PreampFxControl::PresenceDb,12},{0,PreampFxControl::OutputDb,12}}}; std::array<StereoFrame,block> audio{}; std::array<float,windowFrames> tail{}; double peak=0,squares=0; for(std::uint32_t start=0;start<frames;start+=block){for(std::uint32_t i=0;i<block;++i){double ph=2*pi*item.hz*(start+i)/sr;float s=.72f*static_cast<float>(std::sin(ph));audio[i]={s,s};} if(!proc.processBlock(start,audio.data(),block,start==0?ev.data():nullptr,start==0?8U:0U)) return {item.name,-2,0,-2,-2,-2,-2}; for(std::uint32_t i=0;i<block;++i){auto n=start+i; peak=std::max(peak,static_cast<double>(std::max(std::fabs(audio[i].left),std::fabs(audio[i].right)))); squares+=static_cast<double>(audio[i].left)*audio[i].left+static_cast<double>(audio[i].right)*audio[i].right; if(n>=frames-windowFrames) tail[n-(frames-windowFrames)]=audio[i].left;}} double sumW=0; for(std::uint32_t n=0;n<windowFrames;++n) sumW+=.5-.5*std::cos(2*pi*n/(windowFrames-1)); std::array<double,9> amps{}; for(std::uint32_t h=1;h<=amps.size();++h){double f=std::fmod(item.hz*h,sr); if(f>sr*.5) f=sr-f; double re=0,im=0; for(std::uint32_t n=0;n<windowFrames;++n){double w=.5-.5*std::cos(2*pi*n/(windowFrames-1));double a=2*pi*f*n/sr; re+=w*tail[n]*std::cos(a); im-=w*tail[n]*std::sin(a);} amps[h-1]=2*std::hypot(re,im)/sumW;} double harmonic=0; for(std::size_t i=1;i<amps.size();++i) harmonic+=amps[i]*amps[i]; return {item.name,gPreCabinetPeak,gPreCabinetSamplesOver16,peak,std::sqrt(squares/(2.0*frames)),amps[0],std::sqrt(harmonic)/std::max(1.0e-15,amps[0])}; }
}
int main(){const std::array<Case,5> cases{{{"100Hz",100},{"800Hz",800},{"3800Hz",3800},{"5200Hz",5200},{"10000Hz",10000}}}; std::printf("{\"schemaVersion\":1,\"suite\":\"preamp-max-control-before-after-harmonics\",\"sampleRate\":48000,\"inputPeak\":0.72,\"settings\":{\"drive\":24,\"bassDb\":12,\"midDb\":12,\"trebleDb\":12,\"presenceDb\":12,\"outputDb\":12},\"windowFrames\":8192,\"window\":\"hann\",\"harmonics\":[1,9],\"cases\":["); bool good=true; for(std::size_t i=0;i<cases.size();++i){gPreCabinetPeak=0;gPreCabinetSamplesOver16=0;auto r=run(cases[i]);if(i)std::printf(",");std::printf("{\"name\":\"%s\",\"preCabinetPeak\":%.9g,\"wouldClip16Samples\":%llu,\"outputPeak\":%.9g,\"outputRms\":%.9g,\"fundamentalAmplitude\":%.9g,\"harmonicToFundamental\":%.9g}",r.name,r.prePeak,(unsigned long long)r.over,r.outPeak,r.outRms,r.fundamental,r.thd);good=good&&r.prePeak>=0&&r.outPeak>=0;}std::printf("],\"failures\":%u}\n",good?0U:1U);return good?0:1;}
